class Traveller {
  + Name : string
  + BillingInformation : string
  + CompanyName : string
  + CompanyAddress : string
  + TravelPreferences : string[]
  + ReliabilityRating : float
}

class Hotel {
  + Name : string
  + Address : string
  + Rating : int
}

class HotelChain {
  + Name : string
}

class City {
  + Name : string
}

class RoomType {
  + Type : string
}

class Booking {
  + BookingIdentifier : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : RoomType
  + MaxCostPerNight : float
  + Status : string
  + CancellationDeadline : date
}

class SpecialOffer {
  + Price : float
  + CityArea : string
  + HotelRating : int
  + KeyPreferences : string[]
}

class CreditCardInfo {
  + CardDetails : string
}

enum PaymentMethod {
  PrePaid
  PaidAtHotel
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MinRating : int
  + MaxCostPerNight : float
  + Preferences : string[]
}

class HotelOffer {
  + Price : float
  + Availability : boolean
}

Hotel "0..*" -- "1" HotelChain
Hotel "1" -- "1" City
Hotel "1" -- "*" HotelOffer
Hotel "1" -- "*" Booking
Hotel "1" -- "1" City
Hotel "1" -- "1" Address : "located at"

class Address {
  + Street : string
  + City : string
}

Hotel "1" -- "1" Address

Traveller "1" -- "*" Booking
Traveller "1" -- "1" CreditCardInfo
Traveller "1" -- "*" SpecialOffer : "receives"

Booking "1" -- "1" CreditCardInfo
Booking "1" -- "1" PaymentMethod
Booking "1" -- "1" Hotel : "is confirmed by"
Booking "1" -- "1" HotelOffer : "is for"

SpecialOffer "*" -- "1" Traveller : "offered to"
SpecialOffer "*" -- "1" Hotel : "provided by"

SearchCriteria ..> HotelOffer : "filters"

@enduml

